class Solution {
public:
    int maxRepeating(string sequence, string word) {
        int n = sequence.size();
        int m = word.size();
        int ans = 0;
        for (int i = 0; i < n; i++) {
            int k = 0;
            int j = i;
            while (j + m <= n && sequence.compare(j, m, word) == 0) {
                k++;
                j += m;
            }
            if (k > ans) ans = k;
        }
        return ans;
    }
};
